-- Generated from CVIDEO_Recruitment_Taxonomy_AR_EN (Launch Edition / O*NET 31.0).
-- The seed is additive and idempotent: stable workbook codes are upsert keys.

ALTER TABLE categories ADD COLUMN IF NOT EXISTS display_order integer NOT NULL DEFAULT 0;
ALTER TABLE subcategories ADD COLUMN IF NOT EXISTS display_order integer NOT NULL DEFAULT 0;
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS category_id uuid REFERENCES categories(id) ON DELETE SET NULL;
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS primary_subcategory_id uuid REFERENCES subcategories(id) ON DELETE SET NULL;
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS display_order integer NOT NULL DEFAULT 0;
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS onet_soc_code varchar(16);
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS source varchar(80);
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS arabic_review_required boolean NOT NULL DEFAULT false;
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS source_url text;
ALTER TABLE skills ADD COLUMN IF NOT EXISTS category_id uuid REFERENCES categories(id) ON DELETE SET NULL;
ALTER TABLE skills ADD COLUMN IF NOT EXISTS skill_type_en varchar(80);
ALTER TABLE skills ADD COLUMN IF NOT EXISTS skill_type_ar varchar(80);

CREATE TABLE IF NOT EXISTS subcategory_relations (
  subcategory_id uuid NOT NULL REFERENCES subcategories(id) ON DELETE CASCADE,
  related_subcategory_id uuid NOT NULL REFERENCES subcategories(id) ON DELETE CASCADE,
  position integer NOT NULL CHECK (position BETWEEN 1 AND 2),
  PRIMARY KEY (subcategory_id, related_subcategory_id),
  UNIQUE (subcategory_id, position),
  CHECK (subcategory_id <> related_subcategory_id)
);

CREATE TABLE IF NOT EXISTS job_title_subcategories (
  job_title_id uuid NOT NULL REFERENCES job_titles(id) ON DELETE CASCADE,
  subcategory_id uuid NOT NULL REFERENCES subcategories(id) ON DELETE CASCADE,
  position integer NOT NULL CHECK (position BETWEEN 1 AND 2),
  PRIMARY KEY (job_title_id, subcategory_id),
  UNIQUE (job_title_id, position)
);

CREATE TABLE IF NOT EXISTS job_title_aliases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(100) NOT NULL UNIQUE,
  job_title_id uuid NOT NULL REFERENCES job_titles(id) ON DELETE CASCADE,
  alias_en varchar(180) NOT NULL,
  alias_ar varchar(180) NOT NULL,
  onet_soc_code varchar(16),
  arabic_review_required boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true
);
CREATE INDEX IF NOT EXISTS job_title_aliases_job_title_idx ON job_title_aliases(job_title_id);
CREATE INDEX IF NOT EXISTS job_title_aliases_alias_en_idx ON job_title_aliases(lower(alias_en));
CREATE INDEX IF NOT EXISTS job_title_aliases_alias_ar_idx ON job_title_aliases(lower(alias_ar));

CREATE TABLE IF NOT EXISTS job_title_skills (
  job_title_id uuid NOT NULL REFERENCES job_titles(id) ON DELETE CASCADE,
  skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE CASCADE,
  rank integer NOT NULL CHECK (rank BETWEEN 1 AND 5),
  importance_en varchar(32) NOT NULL,
  importance_ar varchar(32) NOT NULL,
  PRIMARY KEY (job_title_id, skill_id),
  UNIQUE (job_title_id, rank)
);
CREATE INDEX IF NOT EXISTS job_title_skills_skill_idx ON job_title_skills(skill_id);

